package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.neoforge.credentials.*;
import com.vandorlabs.neoforge.NativeMountedSwitchBlock;
import com.vandorlabs.screen.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
/** Actual private installed Screens/readers replay the independently frozen released rectangle results. */
final class ScreenChipGroupChecks {
 private static int checks;
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Screen chip groups: "+why);}
 private static BlockPos pos(JsonElement element){var a=element.getAsJsonArray();return new BlockPos(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());}
 static void run(ServerLevel level,Map<ScreenFamily,NativeScreenBlock> blocks)throws Exception{
  var screen=blocks.get(ScreenFamily.SCREEN);var chip=(NativeCredentialReaderBlock)BuiltInRegistries.BLOCK.get(ResourceLocation.fromNamespaceAndPath("vandorlabs","reader_geometry_fixture_chip"));var card=(NativeCredentialReaderBlock)BuiltInRegistries.BLOCK.get(ResourceLocation.fromNamespaceAndPath("vandorlabs","reader_geometry_fixture_card"));int profiles=0;
  try(var stream=new java.util.zip.GZIPInputStream(new java.io.FileInputStream(System.getProperty("screenChipGroupsReference")));var reader=new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){
   for(var element:JsonParser.parseReader(reader).getAsJsonObject().getAsJsonArray("cases")){var row=element.getAsJsonObject();var tiles=new ArrayList<NativeScreenEntity>();var all=new ArrayList<BlockPos>();NativeScreenChipGroups.changed(level,BlockPos.ZERO);var state=screen.state(new ScreenFamily.State(row.get("facing").getAsInt(),false,false,false));
    for(var cell:row.getAsJsonArray("cells")){var p=pos(cell);level.getChunkAt(p);level.setBlock(p,state,18);var tile=(NativeScreenEntity)level.getBlockEntity(p);var tag=NativeScreenFactory.choices(ScreenFamily.SCREEN,NativeScreenCatalog.INSTANCE,NativeScreenCatalog.INSTANCE.defaultHousing(),NativeScreenCatalog.INSTANCE.defaultFrame());tag.putInt("PrimarySurfaceTexture",-4);tag.putBoolean("DisplayFit",row.get("plan").getAsInt()==11&&tiles.size()==1);tile.loadWithComponents(tag,level.registryAccess());need(!tile.inert(),"installed Source CHIP choice");tiles.add(tile);all.add(p);}
    for(var raw:row.getAsJsonArray("readers")){var spec=raw.getAsJsonObject();var p=pos(spec.get("pos"));level.getChunkAt(p);var block=spec.get("chip").getAsBoolean()?chip:card;level.setBlock(p,block.defaultBlockState().setValue(NativeMountedSwitchBlock.FACING,Direction.from3DDataValue(spec.get("facing").getAsInt())),18);var owner=(NativeCredentialReaderEntity)level.getBlockEntity(p);var tag=new CompoundTag();tag.putBoolean("ChipSlot",block.chip());if(!spec.get("empty").getAsBoolean())tag.put("InsertedToken",NativeCredentialItems.writeStack(block.chip()?NativeCredentialItems.dataChip(0):NativeCredentialItems.accessCard(0),level.registryAccess()));owner.loadWithComponents(tag,level.registryAccess());need(!owner.inert(),"installed physical reader");all.add(p);}
    var origin=tiles.get(row.get("origin").getAsInt());var group=NativeScreenChipGroups.group(origin);need(group!=null,"installed root group");need(group.owner().equals(pos(row.get("owner"))),"Source owner profile="+profiles);need(Objects.equals(group.reader(),row.get("reader").isJsonNull()?null:pos(row.get("reader"))),"Source first-attached/first-occupied reader profile="+profiles);var expected=new ArrayList<BlockPos>();for(var p:row.getAsJsonArray("members"))expected.add(pos(p));need(group.members().equals(expected),"Source partition/order profile="+profiles);var layout=row.getAsJsonArray("layout");need(group.columns()==layout.get(0).getAsInt()&&group.rows()==layout.get(1).getAsInt()&&group.minColumn()==layout.get(2).getAsInt()&&group.minRow()==layout.get(3).getAsInt(),"Source rectangle profile="+profiles);var box=group.bounds();double[] actual={box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ};for(int i=0;i<6;i++)need(actual[i]==row.getAsJsonArray("bounds").get(i).getAsDouble(),"Source bounds profile="+profiles+" axis="+i);need(NativeScreenChipGroups.group(origin)==group,"warm immutable scalar group identity");
    for(var p:all){var raw=level.getBlockEntity(p);if(raw instanceof NativeCredentialReaderEntity owner){var tag=new CompoundTag();tag.putBoolean("ChipSlot",owner.chip());owner.loadWithComponents(tag,level.registryAccess());}level.setBlock(p,Blocks.AIR.defaultBlockState(),18);}NativeScreenChipGroups.changed(level,origin.getBlockPos());need(NativeScreenChipGroups.group(origin)==null,"stale removed root rejected");profiles++;
   }
  }
  need(profiles==1800,"whole released corpus");boundary(level,screen);limit(level,screen);NativeScreenChipGroups.clear(level);need(NativeScreenChipGroups.retainedBytes()==0,"world retirement releases all scalar cache storage");System.out.println("[vandorlabs][screen-chip-groups] PASS profiles="+profiles+" checks="+checks+" actual private installed Screens/readers");
 }
 private static void limit(ServerLevel level,NativeScreenBlock screen){var base=new BlockPos(960000,100,960000);var positions=new ArrayList<BlockPos>();for(int y=0;y<32;y++)for(int x=0;x<32;x++){var p=base.offset(x,y,0);level.getChunkAt(p);level.setBlock(p,screen.defaultBlockState(),18);positions.add(p);}var owner=(NativeScreenEntity)level.getBlockEntity(base);NativeScreenChipGroups.changed(level,base);long start=System.nanoTime();var group=NativeScreenChipGroups.group(owner);long millis=(System.nanoTime()-start)/1000000;need(group.members().equals(List.of(base)),"1024connectedcells fallback toqueriedsingleton");need(millis<5000,"bounded largest-case preparation milliseconds="+millis);need(NativeScreenChipGroups.retainedBytes()<=4L*1024*1024,"retained byte budget");level.setBlock(positions.get(1023),Blocks.AIR.defaultBlockState(),18);NativeScreenChipGroups.changed(level,base);var below=NativeScreenChipGroups.group(owner);need(below.members().size()==992&&below.columns()==32&&below.rows()==31,"1023cells retainsSource largest992cellrectangle ratherthancutoff");for(var p:positions)level.setBlock(p,Blocks.AIR.defaultBlockState(),18);NativeScreenChipGroups.changed(level,base);System.out.println("[vandorlabs][screen-chip-groups] limit PASS cells1024 singleton milliseconds="+millis);}
 private static void boundary(ServerLevel level,NativeScreenBlock screen){var pos=new BlockPos(920015,100,920015);level.getChunkAt(pos);need(level.getChunkSource().getChunkNow((pos.getX()+1)>>4,pos.getZ()>>4)==null,"fresh east chunk is cold");level.setBlock(pos,screen.defaultBlockState(),18);var owner=(NativeScreenEntity)level.getBlockEntity(pos);NativeScreenChipGroups.changed(level,pos);var group=NativeScreenChipGroups.group(owner);need(group.members().equals(List.of(pos))&&group.reader()==null&&level.getChunkSource().getChunkNow((pos.getX()+1)>>4,pos.getZ()>>4)==null,"discovery leaves specific adjacent chunk cold");for(int i=0;i<12000;i++)need(NativeScreenChipGroups.group(owner)==group,"warm identity");var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread);for(int i=0;i<10000;i++)NativeScreenChipGroups.group(owner);long bytes=meter.getThreadAllocatedBytes(thread)-before;need(bytes<=1024,"10000warm queries bounded allocation="+bytes);try{java.util.concurrent.CompletableFuture.supplyAsync(()->NativeScreenChipGroups.group(owner)).join();throw new AssertionError("worker discovery accepted");}catch(java.util.concurrent.CompletionException expected){need(expected.getCause() instanceof IllegalStateException,"worker refused before chunk access");}NativeScreenChipGroups.changed(level,pos);need(NativeScreenChipGroups.group(owner)!=group,"explicit invalidation rebuilds scalar layout");level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);NativeScreenChipGroups.changed(level,pos);System.out.println("[vandorlabs][screen-chip-groups] boundary PASS cold/worker/warm10000allocated="+bytes);}

}
